from datetime import date

completed = set()

def run_reminder(learner_id, today):
    key = f'{learner_id}:{today.isoformat()}'
    if key in completed:
        return {'status': 'skipped', 'reason': 'already_sent'}
    completed.add(key)
    return {'status': 'sent', 'run_key': key}

assert run_reminder('ana', date(2026, 10, 2))['status'] == 'sent'
assert run_reminder('ana', date(2026, 10, 2))['status'] == 'skipped'
